+int testRecord(Object o) {
+    int result = 0;
+    switch(o) {
+        case null:
+            result += 1;
+        case R(Integer _):
+            result += 10;
+        case R(Number _):
+            result += 100;
+        case R(String _):
+            result += 1_000;
+        case R(CharSequence _):
+            result += 10_000;
+        case R(_):
+            result += 100_000;
+        default:
+            result += 1000_000;
+    }
+    return result;
+}
+
+int testRecordFactorOut(Object o) {
+    int result = 0;
+    switch(o) {
+        case null:
+        case R(Integer _):
+            result += 1;
+            break;
+        case R(Number _):
+            result += 2;
+            break;
+        default:
+            result += 4;
+            break;
+    }
+    return result;
+}
